changeSet.sql:
-- 1. Colonnes sur table fournisseurs
ALTER TABLE IF EXISTS fournisseurs
    ADD COLUMN IF NOT EXISTS type_fournisseur VARCHAR(30) DEFAULT 'NATIONAL',
    ADD COLUMN IF NOT EXISTS devise VARCHAR(10) DEFAULT 'MAD';

UPDATE fournisseurs
SET type_fournisseur = 'NATIONAL'
WHERE type_fournisseur IS NULL;

UPDATE fournisseurs
SET devise = 'MAD'
WHERE devise IS NULL;

-- 2. Colonne sur table commandes
ALTER TABLE IF EXISTS commandes
    ADD COLUMN IF NOT EXISTS devise VARCHAR(10) DEFAULT 'MAD';

UPDATE commandes
SET devise = 'MAD'
WHERE devise IS NULL;
